record LexRequest { text: Text }
record LexResult { position: Number }

fn closing_quote(text: Text) -> Number {
  var position = 1
  while position < text.length() {
    let character = text.slice(position, position + 1)
    if character == "\"" and text.slice(position - 1, position) != "\\" { return position }
    position += 1
  }
  return -1
}

fn lex_result(request: LexRequest) -> LexResult {
  return {position: closing_quote(request.text)}
}

workflow main(request: LexRequest) -> LexResult {
  result = lex_result(request)
}

